#include <windows.h>
#include <tlhelp32.h>
#include <array>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <iomanip>
#include <string>
#include <vector>
#include <algorithm>

struct Host { DWORD pid=0; std::uintptr_t base=0; };
struct Bucket { std::int64_t token=0; std::int64_t ts=0; std::uint32_t rate=0; std::uint32_t den=0; };

template<class T> static bool rv(HANDLE h,std::uintptr_t a,T& v){SIZE_T n=0;return ReadProcessMemory(h,(LPCVOID)a,&v,sizeof(v),&n)&&n==sizeof(v);} 
static Host findHost(){Host out{};HANDLE ps=CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0);if(ps==INVALID_HANDLE_VALUE)return out;PROCESSENTRY32W pe{};pe.dwSize=sizeof(pe);if(!Process32FirstW(ps,&pe)){CloseHandle(ps);return out;}do{if(_wcsicmp(pe.szExeFile,L"baidunetdiskhost.exe"))continue;HANDLE ms=CreateToolhelp32Snapshot(TH32CS_SNAPMODULE|TH32CS_SNAPMODULE32,pe.th32ProcessID);if(ms==INVALID_HANDLE_VALUE)continue;MODULEENTRY32W me{};me.dwSize=sizeof(me);if(Module32FirstW(ms,&me))do{if(!_wcsicmp(me.szModule,L"kernel.dll")){out.pid=pe.th32ProcessID;out.base=(std::uintptr_t)me.modBaseAddr;CloseHandle(ms);CloseHandle(ps);return out;}}while(Module32NextW(ms,&me));CloseHandle(ms);}while(Process32NextW(ps,&pe));CloseHandle(ps);return out;}
static bool parseHex16(const std::string&s,std::array<unsigned char,16>&out){if(s.size()!=32)return false;auto nib=[](char c)->int{if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;};for(int i=0;i<16;i++){int a=nib(s[i*2]),b=nib(s[i*2+1]);if(a<0||b<0)return false;out[i]=(unsigned char)((a<<4)|b);}return true;}
static bool readBucket(HANDLE h,std::uintptr_t a,Bucket&b){return rv(h,a+0x10,b.token)&&rv(h,a+0x18,b.ts)&&rv(h,a+0x20,b.rate)&&rv(h,a+0x24,b.den);} 
static std::uintptr_t findLiveEntity(HANDLE h,std::uintptr_t entityVt,const std::array<unsigned char,16>&id,std::uintptr_t&ng){SYSTEM_INFO si{};GetSystemInfo(&si);for(std::uintptr_t p=(std::uintptr_t)si.lpMinimumApplicationAddress;p<(std::uintptr_t)si.lpMaximumApplicationAddress;){MEMORY_BASIC_INFORMATION m{};if(!VirtualQueryEx(h,(LPCVOID)p,&m,sizeof(m)))break;auto st=(std::uintptr_t)m.BaseAddress;size_t sz=(size_t)m.RegionSize;bool ok=m.State==MEM_COMMIT&&m.Type==MEM_PRIVATE&&!(m.Protect&PAGE_GUARD)&&!(m.Protect&PAGE_NOACCESS)&&sz<=64ull*1024*1024;if(ok){std::vector<unsigned char>b(sz);SIZE_T got=0;if(ReadProcessMemory(h,(LPCVOID)st,b.data(),sz,&got)){for(size_t i=0;i+0x118<=got;i+=8){std::uintptr_t vt=0;std::memcpy(&vt,b.data()+i,8);if(vt!=entityVt)continue;if(std::memcmp(b.data()+i+0x24,id.data(),16))continue;std::uintptr_t n=0;std::memcpy(&n,b.data()+i+0x108,8);if(n){ng=n;return st+i;}}}}auto nx=st+sz;if(nx<=p)break;p=nx;}return 0;}
static void pb(const char*n,const Bucket&b){std::cout<<n<<" rate="<<b.rate<<" token="<<b.token<<" ts="<<b.ts<<" den="<<b.den;}
int main(int argc,char**argv){if(argc<2){std::cerr<<"taskid required\n";return 2;}std::array<unsigned char,16> id{};if(!parseHex16(argv[1],id))return 3;int interval=argc>2?std::max(10,std::atoi(argv[2])):20;int duration=argc>3?std::max(1,std::atoi(argv[3])):20;Host host=findHost();if(!host.base)return 4;HANDLE h=OpenProcess(PROCESS_QUERY_INFORMATION|PROCESS_VM_READ,FALSE,host.pid);if(!h)return 5;IO_COUNTERS io0{}; GetProcessIoCounters(h,&io0);std::uintptr_t ng=0;auto ent=findLiveEntity(h,host.base+0x13500C8,id,ng);if(!ent||!ng){std::cerr<<"live EntityTask/NetGrid not found\n";CloseHandle(h);return 6;}std::uintptr_t ngvt=0;rv(h,ng,ngvt);std::cout<<"mode=read-only pid="<<host.pid<<" entity=0x"<<std::hex<<ent<<" netgrid=0x"<<ng<<" netgrid_vt_rva=0x"<<(ngvt-host.base)<<std::dec<<" interval_ms="<<interval<<" duration_s="<<duration<<"\n";
Bucket prevU{},prevD{},prevC{},prevT{};bool have=false;std::uint64_t samples=0,cdnZero=0,cdnLow=0,cdnChanges=0,totalChanges=0,totalLow16k=0,totalHigh100k=0,printed=0;std::int64_t minC=INT64_MAX,maxC=INT64_MIN,minT=INT64_MAX,maxT=INT64_MIN,minD=INT64_MAX,maxD=INT64_MIN;ULONGLONG start=GetTickCount64();while(GetTickCount64()-start<(ULONGLONG)duration*1000ULL){Bucket u{},d{},c{},t{};if(!readBucket(h,ng+0x30,u)||!readBucket(h,ng+0x60,d)||!readBucket(h,ng+0x90,c)||!readBucket(h,host.base+0x17C0118+0x70,t)){std::cerr<<"read failed\n";break;}minC=std::min(minC,c.token);maxC=std::max(maxC,c.token);minT=std::min(minT,t.token);maxT=std::max(maxT,t.token);minD=std::min(minD,d.token);maxD=std::max(maxD,d.token);if(c.token<=0)cdnZero++;if(c.token<4096)cdnLow++;if(t.token<16384)totalLow16k++;if(t.token>102400)totalHigh100k++;bool ch=!have||u.token!=prevU.token||u.ts!=prevU.ts||u.rate!=prevU.rate||d.token!=prevD.token||d.ts!=prevD.ts||d.rate!=prevD.rate||c.token!=prevC.token||c.ts!=prevC.ts||c.rate!=prevC.rate||t.token!=prevT.token||t.ts!=prevT.ts||t.rate!=prevT.rate;if(have){if(c.token!=prevC.token||c.ts!=prevC.ts)cdnChanges++;if(t.token!=prevT.token||t.ts!=prevT.ts)totalChanges++;}if(ch&&printed<50){std::cout<<"sample="<<samples<<" wall_ms="<<(GetTickCount64()-start)<<" ";pb("TASK_UP",u);std::cout<<" ";pb("TASK_DL",d);std::cout<<" ";pb("TASK_CDN",c);std::cout<<" ";pb("GLOBAL_TOTAL",t);std::cout<<"\n";printed++;}prevU=u;prevD=d;prevC=c;prevT=t;have=true;samples++;Sleep(interval);}IO_COUNTERS io1{}; GetProcessIoCounters(h,&io1);std::cout<<"SUMMARY samples="<<samples<<" task_cdn_min="<<minC<<" task_cdn_max="<<maxC<<" task_cdn_zero="<<cdnZero<<" task_cdn_lt4k="<<cdnLow<<" task_cdn_changes="<<cdnChanges<<" global_total_min="<<minT<<" global_total_max="<<maxT<<" global_total_changes="<<totalChanges<<" global_total_lt16k="<<totalLow16k<<" global_total_gt100k="<<totalHigh100k<<" task_dl_min="<<minD<<" task_dl_max="<<maxD<<" proc_read_bytes_delta="<<(io1.ReadTransferCount-io0.ReadTransferCount)<<" proc_write_bytes_delta="<<(io1.WriteTransferCount-io0.WriteTransferCount)<<" proc_other_bytes_delta="<<(io1.OtherTransferCount-io0.OtherTransferCount)<<"\n";CloseHandle(h);return 0;}
